-- PrettyBills: invoices, clients, items, activity and workspace defaults.
-- Everything a signed-in user creates lives here, owned by them and guarded by
-- row level security. Run after 20261125000000_profiles.sql, in Supabase →
-- SQL Editor or with `supabase db push`. Safe to re-run.
--
-- Money is integer paise (bigint). Dates are ISO dates in the business's
-- calendar. Ids are generated by the app (the editor works offline first).

create schema if not exists private;

create or replace function private.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

revoke execute on function private.touch_updated_at() from public, anon, authenticated;

-- ===========================================================================
-- Workspace defaults: business details, payment details, terms and signature
-- that every new invoice starts with. One row per user.
-- ===========================================================================
create table if not exists public.workspace_settings (
  user_id    uuid        primary key default auth.uid() references auth.users (id) on delete cascade,
  business   jsonb       check (business is null or (jsonb_typeof(business) = 'object' and pg_column_size(business) <= 4000000)),
  payment    jsonb       check (payment is null or (jsonb_typeof(payment) = 'object' and pg_column_size(payment) <= 100000)),
  terms      text        check (char_length(terms) <= 4000),
  signature  jsonb       check (signature is null or (jsonb_typeof(signature) = 'object' and pg_column_size(signature) <= 4000000)),
  updated_at timestamptz not null default now()
);

comment on table public.workspace_settings is 'Defaults applied to each new invoice. One row per user.';

-- ===========================================================================
-- Clients (recipients). Ids come from the app and are unique per user.
-- ===========================================================================
create table if not exists public.clients (
  user_id    uuid        not null default auth.uid() references auth.users (id) on delete cascade,
  id         text        not null check (id ~ '^[A-Za-z0-9_-]{1,64}$'),
  name       text        not null check (char_length(name) between 1 and 200),
  legal_name text        check (char_length(legal_name) <= 200),
  gstin      text        check (char_length(gstin) <= 15),
  pan        text        check (char_length(pan) <= 10),
  email      text        check (char_length(email) <= 254),
  phone      text        check (char_length(phone) <= 32),
  website    text        check (char_length(website) <= 200),
  address    jsonb       not null default '{}'::jsonb check (jsonb_typeof(address) = 'object' and pg_column_size(address) <= 4000),
  state_code text        generated always as (address ->> 'stateCode') stored,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, id)
);

comment on table public.clients is 'People and businesses a user bills.';

-- the primary key already covers lookups by user_id
create index if not exists clients_user_name_idx on public.clients (user_id, lower(name));

-- ===========================================================================
-- Items & services catalog.
-- ===========================================================================
create table if not exists public.items (
  user_id      uuid          not null default auth.uid() references auth.users (id) on delete cascade,
  id           text          not null check (id ~ '^[A-Za-z0-9_-]{1,64}$'),
  name         text          not null check (char_length(name) between 1 and 200),
  description  text          check (char_length(description) <= 1000),
  hsn_sac      text          check (char_length(hsn_sac) <= 10),
  unit         text          not null default 'pcs' check (char_length(unit) between 1 and 20),
  rate         bigint        not null default 0 check (rate >= 0),
  tax_rate     numeric(5, 2) not null default 0 check (tax_rate between 0 and 100),
  tax_category text          not null default 'taxable' check (tax_category in ('taxable', 'exempt', 'nil')),
  created_at   timestamptz   not null default now(),
  updated_at   timestamptz   not null default now(),
  primary key (user_id, id)
);

comment on table public.items is 'Reusable line items: goods and services with HSN/SAC, unit, rate and GST.';

create index if not exists items_user_name_idx on public.items (user_id, lower(name));

-- ===========================================================================
-- Invoices. `data` is the full invoice document the editor works with; the
-- other columns are copies of what lists, search and reports need, so those
-- never read the (possibly large) document.
-- ===========================================================================
create table if not exists public.invoices (
  id             text        primary key check (id ~ '^[A-Za-z0-9_-]{1,96}$'),
  user_id        uuid        not null default auth.uid() references auth.users (id) on delete cascade,
  number         text        not null default '' check (char_length(number) <= 40),
  status         text        not null default 'draft' check (status in ('draft', 'sent', 'viewed', 'partially_paid', 'paid', 'void')),
  client_id      text        check (char_length(client_id) <= 64),
  client_name    text        check (char_length(client_name) <= 200),
  issue_date     date        not null,
  due_date       date,
  currency       text        not null default 'INR' check (currency ~ '^[A-Z]{3}$'),
  total          bigint      not null default 0,
  amount_paid    bigint      not null default 0 check (amount_paid >= 0),
  balance_due    bigint      generated always as (greatest(total - amount_paid, 0)) stored,
  missing_fields smallint    not null default 0 check (missing_fields >= 0),
  template_id    text        check (char_length(template_id) <= 40),
  data           jsonb       not null check (jsonb_typeof(data) = 'object' and pg_column_size(data) <= 15000000),
  public_token   text        unique check (public_token ~ '^[A-Za-z0-9_-]{16,96}$'),
  link_active    boolean     not null default true,
  sent_at        timestamptz,
  viewed_at      timestamptz,
  paid_at        timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

comment on table public.invoices is 'GST invoices. data holds the full document; other columns are for lists and reports.';
comment on column public.invoices.missing_fields is 'Required fields still empty when last saved. 0 means ready to send.';

-- invoice numbers are unique per user (blank numbers are allowed while drafting)
create unique index if not exists invoices_user_number_key on public.invoices (user_id, number) where number <> '';
-- one index per list the app shows
create index if not exists invoices_user_updated_idx on public.invoices (user_id, updated_at desc);
create index if not exists invoices_user_status_idx on public.invoices (user_id, status, issue_date desc);
create index if not exists invoices_user_due_idx on public.invoices (user_id, due_date) where status in ('sent', 'viewed', 'partially_paid');
create index if not exists invoices_user_client_idx on public.invoices (user_id, client_id);

-- ===========================================================================
-- Activity: sent, viewed, downloaded, paid… The invoice timeline and the
-- "viewed" badge come from here.
-- ===========================================================================
create table if not exists public.invoice_events (
  id         bigint      generated always as identity primary key,
  invoice_id text        not null references public.invoices (id) on delete cascade,
  user_id    uuid        not null default auth.uid() references auth.users (id) on delete cascade,
  type       text        not null check (type in ('created', 'sent', 'viewed', 'downloaded', 'paid', 'reminded', 'voided')),
  at         timestamptz not null default now(),
  meta       jsonb       check (meta is null or pg_column_size(meta) <= 2000)
);

comment on table public.invoice_events is 'What happened to each invoice, newest last.';

create index if not exists invoice_events_invoice_idx on public.invoice_events (invoice_id, at desc);
create index if not exists invoice_events_user_idx on public.invoice_events (user_id, at desc);

-- ===========================================================================
-- updated_at
-- ===========================================================================
drop trigger if exists workspace_settings_touch on public.workspace_settings;
create trigger workspace_settings_touch before update on public.workspace_settings for each row execute function private.touch_updated_at();
drop trigger if exists clients_touch on public.clients;
create trigger clients_touch before update on public.clients for each row execute function private.touch_updated_at();
drop trigger if exists items_touch on public.items;
create trigger items_touch before update on public.items for each row execute function private.touch_updated_at();
drop trigger if exists invoices_touch on public.invoices;
create trigger invoices_touch before update on public.invoices for each row execute function private.touch_updated_at();

-- ===========================================================================
-- Privileges: signed-out visitors get nothing (shared links go through the
-- two functions below). Signed-in users get exactly what the app needs.
-- ===========================================================================
revoke all on public.workspace_settings, public.clients, public.items, public.invoices, public.invoice_events from anon, authenticated;

grant select, insert, update on public.workspace_settings to authenticated;
grant select, insert, update, delete on public.clients, public.items, public.invoices to authenticated;
grant select, insert on public.invoice_events to authenticated;

-- ===========================================================================
-- Row level security: every row belongs to one user.
-- (select auth.uid()) is evaluated once per statement, not once per row.
-- ===========================================================================
alter table public.workspace_settings enable row level security;
alter table public.clients enable row level security;
alter table public.items enable row level security;
alter table public.invoices enable row level security;
alter table public.invoice_events enable row level security;

drop policy if exists workspace_settings_own on public.workspace_settings;
create policy workspace_settings_own on public.workspace_settings
  for all to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

drop policy if exists clients_own on public.clients;
create policy clients_own on public.clients
  for all to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

drop policy if exists items_own on public.items;
create policy items_own on public.items
  for all to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

drop policy if exists invoices_own on public.invoices;
create policy invoices_own on public.invoices
  for all to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

drop policy if exists invoice_events_select_own on public.invoice_events;
create policy invoice_events_select_own on public.invoice_events
  for select to authenticated
  using ((select auth.uid()) = user_id);

-- events can only be added to your own invoices
drop policy if exists invoice_events_insert_own on public.invoice_events;
create policy invoice_events_insert_own on public.invoice_events
  for insert to authenticated
  with check (
    (select auth.uid()) = user_id
    and exists (select 1 from public.invoices i where i.id = invoice_id and i.user_id = (select auth.uid()))
  );

-- ===========================================================================
-- Shared links. Whoever has an invoice's random token may read it (while the
-- link is on) and report views and downloads. Nothing else is reachable.
-- ===========================================================================
create or replace function public.shared_invoice(p_token text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select i.data || jsonb_build_object('status', i.status, 'publicToken', i.public_token, 'linkActive', i.link_active)
  from public.invoices i
  where i.public_token = p_token
    and i.link_active
    and i.status <> 'void'
$$;

comment on function public.shared_invoice(text) is 'The invoice behind a shared link, or null if the link is off or unknown.';

-- returns true for the first event of its kind, false for a repeat, null for an unknown link
create or replace function public.track_shared_invoice(p_token text, p_type text)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_id     text;
  v_user   uuid;
  v_status text;
  v_first  boolean;
begin
  if p_type not in ('viewed', 'downloaded') then
    raise exception 'unsupported event type: %', p_type using errcode = '22023';
  end if;

  select i.id, i.user_id, i.status into v_id, v_user, v_status
  from public.invoices i
  where i.public_token = p_token and i.link_active and i.status <> 'void';
  if v_id is null then
    return null;
  end if;

  v_first := not exists (select 1 from public.invoice_events e where e.invoice_id = v_id and e.type = p_type);

  -- one event per kind per minute is plenty; ignore refresh storms
  if not v_first and exists (
    select 1 from public.invoice_events e
    where e.invoice_id = v_id and e.type = p_type and e.at > now() - interval '1 minute'
  ) then
    return false;
  end if;

  insert into public.invoice_events (invoice_id, user_id, type) values (v_id, v_user, p_type);

  if p_type = 'viewed' and v_first then
    update public.invoices
    set viewed_at = now(),
        status = case when status = 'sent' then 'viewed' else status end,
        data = case when status = 'sent' then jsonb_set(data, '{status}', '"viewed"') else data end
    where id = v_id;
  end if;

  return v_first;
end;
$$;

comment on function public.track_shared_invoice(text, text) is 'Records a view or download of a shared invoice. The first view marks a sent invoice as viewed.';

revoke all on function public.shared_invoice(text) from public;
revoke all on function public.track_shared_invoice(text, text) from public;
grant execute on function public.shared_invoice(text) to anon, authenticated;
grant execute on function public.track_shared_invoice(text, text) to anon, authenticated;

-- ===========================================================================
-- Overview numbers for the dashboard and sidebar, in one round trip.
-- Runs as the caller, so RLS limits it to their invoices. `p_today` is the
-- user's local date (overdue is a calendar question, not a UTC one).
-- ===========================================================================
create or replace function public.invoice_overview(p_today date)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  with mine as (
    select
      i.status, i.total, i.balance_due, i.missing_fields, i.paid_at, i.issue_date,
      (i.status in ('sent', 'viewed', 'partially_paid')) as open,
      (i.status in ('sent', 'viewed', 'partially_paid') and i.due_date < p_today and i.balance_due > 0) as late
    from public.invoices i
    where i.user_id = (select auth.uid())
  )
  select jsonb_build_object(
    'all',               count(*),
    'drafts',            count(*) filter (where status = 'draft'),
    'drafts_ready',      count(*) filter (where status = 'draft' and missing_fields = 0),
    'sent',              count(*) filter (where open and not late),
    'overdue',           count(*) filter (where late),
    'paid',              count(*) filter (where status = 'paid'),
    'outstanding',       coalesce(sum(balance_due) filter (where open), 0),
    'overdue_amount',    coalesce(sum(balance_due) filter (where late), 0),
    'collected_month',   coalesce(sum(total) filter (where status = 'paid' and paid_at >= date_trunc('month', p_today::timestamp)), 0),
    'invoiced_month',    coalesce(sum(total) filter (where status not in ('draft', 'void') and issue_date >= date_trunc('month', p_today::timestamp)::date), 0),
    'invoiced_month_count', count(*) filter (where status not in ('draft', 'void') and issue_date >= date_trunc('month', p_today::timestamp)::date)
  )
  from mine
$$;

revoke all on function public.invoice_overview(date) from public;
grant execute on function public.invoice_overview(date) to authenticated;
